<script setup lang="ts">
import { onActivated, onBeforeUnmount, reactive, ref } from 'vue';
import { api, user, lead, roleNames, type User } from '../auth';
import { preferences } from '../platform';
import { ask, toast } from '../store';
import { execute } from '../client';
import { downloadJson, invalidateCapabilities } from '../execution';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
const tabs=[['appearance','外观与偏好','sun'],['executor','执行器','terminal'],['ai','AI 引擎','sparkles'],['team','团队','team'],['about','数据与关于','database']];
const tab=ref('appearance'),busy=ref(false),loading=ref(false),error=ref(''),members=ref<User[]>([]),about=ref<any>(),aiState=ref<any>({}),browserResult=ref('');
const executor=reactive({browserPath:'',headless:true,jmeterHome:'',javaHome:''});
const ai=reactive({provider:'OPENAI',baseUrl:'https://api.openai.com/v1',model:'',apiKey:'',anthropicVersion:'2023-06-01'});
const adding=ref(false),member=reactive({username:'',displayName:'',email:'',password:'',role:'TESTER'});
async function load() { loading.value=true;error.value='';try { const [settings,team,info]=await Promise.all([api('platform/settings'),api<User[]>('team'),api('platform/about')]);Object.assign(executor,settings.executor);aiState.value=settings.ai;Object.assign(ai,{...settings.ai,apiKey:''});members.value=team;about.value=info;} catch(e){error.value=(e as Error).message;}finally{loading.value=false;} }
function providerChanged() {ai.baseUrl=ai.provider==='OPENAI'?'https://api.openai.com/v1':'https://api.anthropic.com/v1';ai.apiKey='';ai.model='';}
async function action(fn:()=>Promise<void>) { if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;} }
function saveExecutor() {return action(async()=>{Object.assign(executor,await api('platform/settings/executor','PUT',executor));invalidateCapabilities();toast('执行器设置已保存到数据库');});}
function testBrowser() {return action(async()=>{const result=await execute<any>('browser/test',{});browserResult.value=`可用 · ${result.path}`;toast('浏览器已实际启动并关闭');});}
function saveAi() {return action(async()=>{aiState.value=await api('platform/settings/ai','PUT',ai);ai.apiKey='';toast('AI 配置已加密保存');});}
function testAi() {return action(async()=>{await api('platform/ai/test','POST',{});toast('AI API 已连接，密钥与模型调用成功');});}
async function clearAi() {if(!await ask('移除已保存的 AI 密钥并停用 AI 功能？'))return;return action(async()=>{aiState.value=await api('platform/settings/ai','DELETE');ai.apiKey='';toast('AI 密钥已移除');});}
function openMember(){Object.assign(member,{username:'',displayName:'',email:'',password:'',role:'TESTER'});adding.value=true;error.value='';}
function addMember(){return action(async()=>{await api('team','POST',member);members.value=await api('team');adding.value=false;member.password='';toast('成员已添加');});}
async function changeRole(target:User,event:Event){const select=event.target as HTMLSelectElement,next=select.value;select.value=target.role;if(!await ask(`将 ${target.displayName} 的角色改为“${roleNames[next]}”？`))return;return action(async()=>{members.value=await api(`team/${target.id}/role`,'PUT',{role:next});user.value=await api('auth/me');toast('团队角色已更新');});}
async function remove(target:User){if(!await ask(`删除团队成员“${target.displayName}”？其登录会话将立即失效。`))return;return action(async()=>{members.value=await api(`team/${target.id}`,'DELETE');toast('成员已删除');});}
function exportData(){return action(async()=>{downloadJson(await api('platform/export'),`testpilot-workspace-${new Date().toISOString().slice(0,10)}.json`);});}
function readTab(){if(location.hash.split('?')[0]==='#/settings'){const value=new URLSearchParams(location.hash.split('?')[1]||'').get('tab');if(tabs.some(t=>t[0]===value))tab.value=value!;}}
function setTab(value:string){tab.value=value;location.hash=`#/settings?tab=${value}`;}
onActivated(()=>{readTab();load();});
window.addEventListener('hashchange',readTab);onBeforeUnmount(()=>window.removeEventListener('hashchange',readTab));
</script>
<template><div class="page config-page"><div class="page-heading"><div><div class="eyebrow">YOUR PLATFORM, YOUR CONTROLS</div><h1>平台设置</h1><p>浏览器偏好、共享执行器、远程 AI 与团队权限。</p></div><span :class="['badge',lead?'soft':'neutral']">{{roleNames[user?.role||'']}}</span></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="loading" class="inline-note"><Icon name="loader" class="spin" />正在读取数据库配置…</div><div class="settings-layout"><nav class="settings-nav" aria-label="设置分类"><button v-for="item in tabs" :key="item[0]" :class="{active:tab===item[0]}" @click="setTab(item[0]!)"><Icon :name="item[2]!" />{{item[1]}}</button></nav><section class="card settings-content">
  <template v-if="tab==='appearance'"><div class="settings-heading"><h2>外观与偏好</h2><p>立即生效，保存到当前浏览器。</p></div><div class="setting-row"><div><h3>深色模式</h3><p>为长时间测试切换低亮度界面。</p></div><input v-model="preferences.dark" type="checkbox" role="switch" aria-label="深色模式" class="switch" /></div><div class="setting-row"><div><h3>失败时提醒</h3><p>请求、断言或任务失败时显示提示。</p></div><input v-model="preferences.notifyFailure" type="checkbox" role="switch" aria-label="失败时提醒" class="switch" /></div><div class="setting-row"><div><h3>自动定位报告</h3><p>测试结束后滚动到当前页面的执行结果。</p></div><input v-model="preferences.openReport" type="checkbox" role="switch" aria-label="自动定位报告" class="switch" /></div></template>
  <template v-if="tab==='executor'"><div class="settings-heading"><h2>执行器</h2><p>以下路径指向运行平台的服务器。留空时自动探测。</p></div><p v-if="!lead" class="inline-note">执行器由测试负责人维护，当前账号可以查看和检测。</p><fieldset :disabled="!lead||busy"><label class="field">浏览器可执行文件<input v-model="executor.browserPath" placeholder="留空自动探测 Edge / Chrome" class="mono" aria-label="浏览器路径" /></label><label class="field">JMeter 安装目录<input v-model="executor.jmeterHome" placeholder="例如 D:\apache-jmeter-5.6.3" class="mono" aria-label="JMeter 安装目录" /></label><label class="field">JDK 安装目录<input v-model="executor.javaHome" placeholder="留空自动探测 JDK 21" class="mono" aria-label="JDK 安装目录" /></label><div class="setting-row"><div><h3>无头模式</h3><p>浏览器在后台执行，避免弹出窗口。</p></div><input v-model="executor.headless" type="checkbox" role="switch" aria-label="无头模式" class="switch" /></div></fieldset><div class="config-actions"><button v-if="lead" class="button primary" :disabled="busy" @click="saveExecutor"><Icon name="save" />保存执行器设置</button><button class="button" :disabled="busy" @click="testBrowser">检测已保存的浏览器</button><a href="#/toolchain" class="text-button">检测完整工具链<Icon name="arrow" :size="14" /></a></div><p v-if="browserResult" class="inline-note break-word">{{browserResult}}</p></template>
  <template v-if="tab==='ai'"><div class="settings-heading"><h2>远程 AI 引擎</h2><p>选择 API 协议，配置地址、模型与密钥后才能使用 AI 编排。</p></div><div class="ai-status"><Icon name="sparkles" /><div><strong>{{aiState.configured?'已配置远程 API':'AI 尚未启用'}}</strong><p>{{aiState.configured?`${aiState.provider} · ${aiState.model} · ${aiState.keyHint}`:'未配置时，AI 功能返回明确错误。'}}</p></div><span :class="['badge',aiState.configured?'good':'neutral']">{{aiState.configured?'密钥已保存':'需要 API 密钥'}}</span></div><fieldset :disabled="!lead||busy"><label class="field">API 协议<select v-model="ai.provider" aria-label="AI API 协议" @change="providerChanged"><option value="OPENAI">OpenAI 兼容 · Chat Completions</option><option value="ANTHROPIC">Anthropic 兼容 · Messages</option></select></label><label class="field">API 基础地址<input v-model="ai.baseUrl" aria-label="AI API 基础地址" type="url" class="mono" /></label><label class="field">模型名称<input v-model="ai.model" aria-label="AI 模型名称" placeholder="填写提供方支持的模型 ID" class="mono" /></label><label v-if="ai.provider==='ANTHROPIC'" class="field">Anthropic API 版本<input v-model="ai.anthropicVersion" aria-label="Anthropic API 版本" /></label><label class="field">API 密钥<input v-model="ai.apiKey" type="password" aria-label="AI API 密钥" autocomplete="new-password" :placeholder="aiState.configured?'留空保留原密钥；切换协议或地址需重新填写':'必填，不会返回给浏览器'" /></label></fieldset><div class="config-actions"><button v-if="lead" class="button primary" :disabled="busy" @click="saveAi"><Icon name="save" />保存 AI 设置</button><button class="button" :disabled="busy||!aiState.configured" @click="testAi">测试已保存的 API</button><button v-if="lead&&aiState.configured" class="text-button text-bad" :disabled="busy" @click="clearAi">移除密钥</button></div><p class="inline-note">密钥由后端加密后存入数据库，仅服务端发起模型请求。测试连接会向所选模型发送一条简短请求。</p><p v-if="!lead" class="muted help">只有测试负责人可以修改共享 AI 设置。</p></template>
  <template v-if="tab==='team'"><div class="settings-heading section-title"><div><h2>团队与角色</h2><p>{{members.length}} 位成员 · 权限在服务端校验</p></div><button v-if="lead" class="button primary small" @click="openMember"><Icon name="plus" :size="15" />添加成员</button></div><p v-if="!lead" class="inline-note">当前角色仅能查看团队，添加、删除和角色修改由测试负责人操作。</p><article v-for="person in members" :key="person.id" class="member-row"><div class="member-avatar">{{person.displayName.slice(0,1)}}</div><div class="member-details"><h3>{{person.displayName}} <span v-if="person.id===user?.id" class="badge soft">我</span></h3><p>@{{person.username}} <span v-if="person.email">· {{person.email}}</span></p></div><select v-if="lead" :value="person.role" :aria-label="`${person.displayName} 的角色`" :disabled="busy" @change="changeRole(person,$event)"><option v-for="(label,code) in roleNames" :key="code" :value="code">{{label}}</option></select><span v-else class="badge neutral">{{roleNames[person.role]}}</span><button v-if="lead" class="icon-button" :disabled="busy||person.id===user?.id" :aria-label="`删除成员 ${person.displayName}`" @click="remove(person)"><Icon name="trash" /></button></article><p class="muted help">成员通过账号和密码登录；角色变更下次请求即生效。平台始终保留至少一位测试负责人。</p></template>
  <template v-if="tab==='about'"><div class="settings-heading"><h2>数据与关于</h2><p>根据后端当前连接的数据库与运行环境显示。</p></div><template v-if="about"><div class="database-state"><Icon name="database" :size="28" /><div><h3>{{about.database}} <span :class="['badge',about.connected?'good':'bad']">{{about.connected?'连接正常':'连接异常'}}</span></h3><p>{{about.catalog}} · {{about.databaseVersion}}</p></div></div><div class="about-counts"><div><strong>{{about.counts.projects}}</strong><span>项目</span></div><div><strong>{{about.counts.environments}}</strong><span>环境</span></div><div><strong>{{about.counts.workspaceResources}}</strong><span>工作区资源</span></div><div><strong>{{about.counts.tasks}}</strong><span>后端任务</span></div></div><div class="setting-row"><div><h3>导出工作区</h3><p>导出数据库中的项目、环境、测试配置与脱敏平台设置。包含环境变量原值，请妥善保管。</p></div><button v-if="lead" class="button" :disabled="busy" @click="exportData">导出 JSON</button><span v-else class="badge neutral">仅测试负责人</span></div><dl class="about-details"><dt>应用版本</dt><dd>TestPilot {{about.version}}</dd><dt>后端</dt><dd>{{about.backend}} · Java {{about.javaVersion}}</dd><dt>前端</dt><dd>{{about.frontend}}</dd><dt>存储方式</dt><dd>{{about.storage}}</dd><dt>密钥备份</dt><dd>恢复 AI 配置需同时保留服务器密钥文件或 TESTPILOT_SECRET_KEY。</dd></dl></template></template>
</section></div><Modal v-if="adding" title="添加团队成员" @close="adding=false"><form id="member-form" @submit.prevent="addMember"><div class="two-fields"><label class="field">姓名<input v-model="member.displayName" required maxlength="100" aria-label="成员姓名" /></label><label class="field">账号<input v-model="member.username" required minlength="3" maxlength="80" pattern="[A-Za-z0-9_.-]+" aria-label="成员账号" autocomplete="off" /></label></div><label class="field">邮箱（选填）<input v-model="member.email" type="email" maxlength="200" /></label><label class="field">初始密码<input v-model="member.password" type="password" minlength="10" maxlength="128" required aria-label="成员初始密码" autocomplete="new-password" /></label><label class="field">角色<select v-model="member.role" aria-label="新成员角色"><option v-for="(label,code) in roleNames" :key="code" :value="code">{{label}}</option></select></label><div v-if="error" class="error-banner" role="alert">{{error}}</div></form><template #footer><button class="button" @click="adding=false">取消</button><button form="member-form" class="button primary" :disabled="busy">添加成员</button></template></Modal></div></template>
